package com.example.meetomxh;
import android.content.Intent;
import android.os.Bundle;
import android.widget.*;
import android.text.InputType;
import androidx.appcompat.app.AppCompatActivity;
import com.example.meetomxh.supabase.*;
import org.json.JSONObject;
public class RegisterActivity extends AppCompatActivity {
 @Override protected void onCreate(Bundle state){super.onCreate(state);boolean onboard=SessionManager.getInstance().getCurrentUser()!=null;LinearLayout form=Forms.start(this,onboard?"Hoàn tất hồ sơ":"Đăng ký Meeto");EditText name=Forms.field(form,"Họ và tên",SessionManager.getInstance().pending("signup_name"),InputType.TYPE_CLASS_TEXT);EditText dob=Forms.field(form,"Ngày sinh YYYY-MM-DD",SessionManager.getInstance().pending("signup_dob"),InputType.TYPE_CLASS_DATETIME);EditText gender=Forms.field(form,"Giới tính (không bắt buộc)","",InputType.TYPE_CLASS_TEXT);EditText email=Forms.field(form,"Email","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);EditText pass=Forms.field(form,"Mật khẩu (ít nhất 8 ký tự)","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);email.setVisibility(onboard?android.view.View.GONE:android.view.View.VISIBLE);pass.setVisibility(onboard?android.view.View.GONE:android.view.View.VISIBLE);
 Forms.status(this,"Xác minh email trước khi hoàn tất hồ sơ. Đăng ký bằng số điện thoại/OTP chưa được hỗ trợ.");
 Forms.button(form,onboard?"Hoàn tất hồ sơ":"Đăng ký bằng email",()->{Forms.status(this,"Đang xử lý…");if(onboard){Api.run(()->{JSONObject current=ProfileClient.self();return RpcClient.object("complete_onboarding",Api.obj("p_display_name",name.getText().toString().trim(),"p_birth_date",dob.getText().toString().trim(),"p_gender",gender.getText().toString().trim().isEmpty()?null:gender.getText().toString().trim(),"p_expected_version",current.getLong("version")));},new Api.Callback<JSONObject>(){public void success(JSONObject p){startActivity(new Intent(RegisterActivity.this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));finish();}public void error(String e){Forms.status(RegisterActivity.this,e);}});}else{try{SessionManager.getInstance().pending("signup_name",name.getText().toString());SessionManager.getInstance().pending("signup_dob",dob.getText().toString());}catch(Exception e){Forms.status(this,"Không lưu được thông tin đăng ký.");return;}SupabaseAuthClient.signup(email.getText().toString(),pass.getText().toString(),new Api.Callback<JSONObject>(){public void success(JSONObject r){Forms.status(RegisterActivity.this,"Đã gửi email xác minh. Mở liên kết trong email rồi đăng nhập để hoàn tất hồ sơ.");}public void error(String e){Forms.status(RegisterActivity.this,e);}});}});
 Forms.button(form,"Quay lại đăng nhập",()->{if(onboard)SessionManager.getInstance().signOut();startActivity(new Intent(this,LoginActivity.class));finish();});
 }
}